import java.util.Scanner;
public class Greeter {
    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        System.out.print("Age: ");
        int age = sc.nextInt();
        sc.nextLine();                         // throw away the leftover Enter
        System.out.print("Full name: ");
        String name = sc.nextLine();

        String a = new String("hi"), b = new String("hi");
        System.out.println(a == b);            // false (different objects)
        System.out.println(a.equals(b));       // true  (same text)
        System.out.println("Hello".substring(1, 3)); // el

        if (age >= 18 && name.length() > 0) System.out.println("Welcome " + name);
        else System.out.println("Too young");

        switch (name.toLowerCase()) {
            case "monday": case "tuesday": System.out.println("unwind"); break;
            case "wednesday": System.out.println("break"); break;
            default: System.out.println("party");
        }
    }
}

